  evt rsegs (fun ms' =>
      ms' = MS (mkR (Z_to_bv 64 0x696a8) sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) s3 (Z_to_bv 64 3) (Z_to_bv 64 34) (Z_to_bv 64 (-1)) (Z_to_bv 64 0) a6 a7
